// Changes: Allow valid prefix tokens while bounding malformed-input token
// draining.
static void drain_tokens(Ctx* ctx, size_t limit) {
  for (size_t i = 0; i < limit; ++i) {
    if (read_token(ctx) == EOF_TOKEN)
      return;
  }
  fail("Lexer did not reach an error or EOF within the token limit");
}

